import{_ as t,o,c as a,a5 as i}from"./chunks/framework.B6tQOu6W.js";const n="/assets/entry-point.CRyDggQ3.png",l="/assets/html-php-db-beurk-orig.Df2FMLDG.png",s="/assets/html-php-db-beurk-commente.DUWbF17O.png",r="/assets/3-tiers.C4hEsWEL.jpg",u="/assets/mvc_router.q8JUxRfn.png",p="/assets/route.B60u-BVk.png",c="/assets/routeur.VtuRgW6A.jpg",_=JSON.parse('{"title":"MVC : Le développement organisé","description":"","frontmatter":{},"headers":[],"relativePath":"tp/mvc/support.md","filePath":"tp/mvc/support.md","lastUpdated":1720854982000}'),d={name:"tp/mvc/support.md"};function m(h,e,g,v,f,q){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="mvc-le-developpement-organise" tabindex="-1">MVC : Le développement organisé <a class="header-anchor" href="#mvc-le-developpement-organise" aria-label="Permalink to &quot;MVC : Le développement organisé&quot;">​</a></h1><h2 id="introduction-au-code-professionnel" tabindex="-1">Introduction au code professionnel <a class="header-anchor" href="#introduction-au-code-professionnel" aria-label="Permalink to &quot;Introduction au code professionnel&quot;">​</a></h2><p>Un code professionnel est essentiel pour le développement de projets durables et maintenables. Il se caractérise par plusieurs aspects clés :</p><ul><li>Documentation complète</li><li>Structure modulaire</li><li>Clarté et précision</li><li>Utilisation de termes en anglais</li><li>Réutilisabilité des composants</li><li>Capacité d&#39;évolution</li><li>Organisation permettant le travail en équipe</li></ul><p>L&#39;objectif principal d&#39;un code professionnel est de permettre à une équipe de travailler efficacement et de comprendre rapidement la structure du projet.</p><p>Il s&#39;agit donc de gagner du temps pour les ajouts, les modifications et les évolutions d&#39;un projet.</p><h2 id="l-importance-de-la-structure" tabindex="-1">L&#39;importance de la structure <a class="header-anchor" href="#l-importance-de-la-structure" aria-label="Permalink to &quot;L&#39;importance de la structure&quot;">​</a></h2><h3 id="le-point-d-entree-unique" tabindex="-1">Le point d&#39;entrée unique <a class="header-anchor" href="#le-point-d-entree-unique" aria-label="Permalink to &quot;Le point d&#39;entrée unique&quot;">​</a></h3><p>La structure d&#39;un projet est tout aussi cruciale que le code lui-même. Un élément fondamental est le concept de point d&#39;entrée unique.</p><p>Toutes les requêtes passent par un seul point d&#39;entrée, généralement un fichier <code>index.php</code>, qui se charge ensuite de diriger le flux vers les composants appropriés.</p><p><img src="'+n+'" alt="L&#39;entry Point" loading="lazy"></p><div class="danger custom-block"><p class="custom-block-title">include ?</p><p>Ici, nous utilisons l&#39;include pour inclure les pages dans une autre. Cette technique est très courante en PHP, elle est pourtant parfois risquée. En effet, si vous ne filtrez pas ce que vous tentez d&#39;inclure vous avez créé une faille <strong>grave de sécurité</strong>.</p><p>Ici, nous réduisons le risque en mettant en place ce que l&#39;on appelle une <code>Whiteliste</code> (liste d&#39;autorisations). Cette whiteliste est à mettre en parallèle avec ce que vous connaissez également une <code>Blackliste</code> (liste de filtres).</p><ul><li>Avec une <code>Whiteliste</code> nous allons tout interdire <strong>sauf</strong> ce que nous souhaitons autoriser.</li><li>Avec une <code>Blackliste</code> nous allons tout autoriser <strong>sauf</strong> ce que nous souhaitons interdire.</li></ul><p>La Blackliste est donc moins contraignante pour le développeur… <strong>Mais elle est surtout moins sécurisée</strong>.</p></div><h3 id="evolution-par-rapport-au-code-de-premiere-annee" tabindex="-1">Évolution par rapport au code de première année <a class="header-anchor" href="#evolution-par-rapport-au-code-de-premiere-annee" aria-label="Permalink to &quot;Évolution par rapport au code de première année&quot;">​</a></h3><p>En comparaison avec le code souvent produit en première année d&#39;études, qui mélange fréquemment HTML, PHP et requêtes SQL, une approche plus structurée est nécessaire pour des projets professionnels.</p><p>Exemple d&#39;un code pas ranger :</p><p><img src="'+l+'" alt="HTML, PHP, SQL mélangés" loading="lazy"></p><p>Voici, comment découper / identifier les différentes parties du code à ranger dans une structure type MVC :</p><p><img src="'+s+'" alt="HTML, PHP, SQL mélangés" loading="lazy"></p><h2 id="le-pattern-mvc-modele-vue-controleur" tabindex="-1">Le pattern MVC (Modèle-Vue-Contrôleur) <a class="header-anchor" href="#le-pattern-mvc-modele-vue-controleur" aria-label="Permalink to &quot;Le pattern MVC (Modèle-Vue-Contrôleur)&quot;">​</a></h2><p>Le MVC est un pattern de conception qui permet de séparer les responsabilités au sein d&#39;une application.</p><p>Nous avons ici Trois tiers, mais sachez que plus globalement on parle de développement en N-tiers (N étant un nombre variable).</p><p><img src="'+r+'" alt="3 Parties MVC" loading="lazy"></p><h3 id="modele" tabindex="-1">Modèle <a class="header-anchor" href="#modele" aria-label="Permalink to &quot;Modèle&quot;">​</a></h3><ul><li>Gère la logique de données.</li><li>Interagit avec la base de données.</li><li>En POO, on crée généralement un objet ou entité.</li></ul><div class="tip custom-block"><p class="custom-block-title">Requête ou pas requête ici ?</p><p>En fonction du framework utilisé, plusieurs options sont possibles.</p><ul><li>Laravel =&gt; ORM. Ici nous allons utiliser 100% des options de l&#39;objet. Nous n&#39;aurons donc pas de requête SQL comme vous les connaissez.</li><li>MiniMVC Sample =&gt; Pas d&#39;ORM, ici nous allons utiliser des requêtes classiques avec PDO comme vous le faisiez en première année.</li><li>…</li></ul></div><h3 id="vue" tabindex="-1">Vue <a class="header-anchor" href="#vue" aria-label="Permalink to &quot;Vue&quot;">​</a></h3><ul><li>S&#39;occupe de l&#39;affichage</li><li>Contient le HTML et le minimum de logique d&#39;affichage</li><li>Ne doit pas contenir de logique métier</li></ul><p>::: dange Attention !</p><p>Pas de traitemement ici. Le découpage est la clé de la réussite. Vous devez ici ne faire que la logique d&#39;affichage des données.</p><ul><li>Boucle</li><li>Mise en forme</li><li>Pas d&#39;accès au(x) modèle(s) ici.</li></ul><p>:::</p><h3 id="controleur" tabindex="-1">Contrôleur <a class="header-anchor" href="#controleur" aria-label="Permalink to &quot;Contrôleur&quot;">​</a></h3><ul><li>Fait le lien entre le Modèle et la Vue</li><li>Contient la logique de l&#39;application</li><li>Traite les requêtes, manipule les données via le Modèle, et prépare les données pour la Vue</li></ul><div class="danger custom-block"><p class="custom-block-title">Attention !</p><p>Pas de requête SQL dans un contrôleur. Ici nous <strong>devons</strong> faire appel à un Modèle pour acceder aux données.</p></div><h2 id="le-routeur" tabindex="-1">Le Routeur <a class="header-anchor" href="#le-routeur" aria-label="Permalink to &quot;Le Routeur&quot;">​</a></h2><p>Le routeur est un composant crucial dans une architecture MVC :</p><ul><li>Il définit la correspondance entre les URLs et les actions du contrôleur</li><li>Il dirige les requêtes vers le bon contrôleur et la bonne méthode</li></ul><div class="tip custom-block"><p class="custom-block-title">Comment le représenter ?</p><p>Intéractions entre les composants du MVC :</p><p><img src="'+u+'" alt="Routeur Schema" loading="lazy"></p><p>Comment le lien est traité par le routeur :</p><p><img src="'+p+'" alt="Concrètement" loading="lazy"></p><p>Exemple du code d&#39;un routeur simple :</p><p><img src="'+c+'" alt="Routeur" loading="lazy"></p></div><h2 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h2><p>L&#39;approche MVC représente une évolution significative dans la façon d&#39;organiser et de structurer le code. Elle permet de créer des applications plus maintenables, évolutives et adéquate au travail en équipe.</p><div class="tip custom-block"><p class="custom-block-title">Important</p><p>Bien que plus complexe au départ, cette structure apporte des bénéfices importants sur le long terme, notamment en termes de lisibilité du code et de facilité de maintenance.</p></div>',41)])])}const L=t(d,[["render",m]]);export{_ as __pageData,L as default};
